// Static (hosted, no backend) data mode: NEXT_PUBLIC_DATA_MODE=static. Completed rounds come from files generated by
// scripts/build-static-evidence.mjs (same projection and TEE verification as the API); agent reputation is read live
// from Aurora testnet's public RPC in the browser through the same shared reader the API uses. Read-only: no keys.
import { createPublicClient, http } from "viem";
import { createReputationReader } from "../../../../runtime/agents/reputation-readonly.mjs";
import { createReputationBoard, REPUTATION_STACKS } from "../../../../runtime/agents/reputation-board.mjs";
import originalManifest from "../../../../deployments/aurora-testnet-reputation.json";
import tidepoolManifest from "../../../../deployments/aurora-testnet-tidepool-reputation.json";

export const STATIC_DATA = process.env.NEXT_PUBLIC_DATA_MODE === "static";
export const BUNDLED_HISTORY = STATIC_DATA || process.env.NEXT_PUBLIC_DATA_MODE === "hybrid";
const AURORA_TESTNET_RPC = "https://testnet.aurora.dev";
const FILES: Record<string, string> = {
  "/api/evidence/testnet-rounds": "/evidence/testnet-rounds.json",
  "/api/tidepool/demo": "/evidence/tidepool-demo.json",
};

/** Same-origin file for a read model, or null when the static build has no such data. */
export function staticFile(path: string): string | null { return FILES[path] ?? null; }

type Board = { read: () => Promise<unknown> };
const boards: Partial<Record<"original" | "tidepool", Board>> = {};
/** Browser-side live reputation read (cached 15 s by the shared board). */
export function liveReputation(stack: "original" | "tidepool"): Promise<unknown> {
  if (!boards[stack]) {
    const manifest = stack === "original" ? originalManifest : tidepoolManifest;
    const client = createPublicClient({ transport: http(AURORA_TESTNET_RPC, { retryCount: 1, timeout: 15_000 }) });
    boards[stack] = createReputationBoard({ reader: createReputationReader({ client, manifest }), manifest, stack: REPUTATION_STACKS[stack] });
  }
  return boards[stack]!.read();
}
